const dialogId='workspace-dialog';let returnFocus=null,navigation,requestDialogClose=()=>$('#workspace-dialog').close();
function modal(title,html){$('#workspace-dialog').classList.remove('task-detail-drawer');if(!$('#workspace-dialog').open)returnFocus=document.activeElement;$('#workspace-dialog-title').textContent=title;$('#workspace-dialog .dialog-leave-confirm')?.remove();$('#workspace-dialog-body').innerHTML=html;requestDialogClose=trackDialogForm($('#workspace-dialog'));$( '#'+dialogId).showModal();}
